// jitSnapAskers are the askers by method, nil for one of another argument.
var jitSnapAskers [len(jitSnapNames)]func(s *jitSnapshot, fb *jitFeedback, pc int)

// The askers are set at init: through nest, they ask by this table.
func init() {
	jitSnapAskers = [len(jitSnapNames)]func(s *jitSnapshot, fb *jitFeedback, pc int){
		snapAccessor:       jitSnapAskAccessor,
		snapTypedBigRead:   jitSnapAskTypedBigRead,
		snapFrequency:      jitSnapAskFrequency,
		snapGenSteps:       jitSnapAskGenSteps,
		snapInlineExit:     jitSnapAskInlineExit,
		snapKeyedWrite:     jitSnapAskKeyedWrite,
		snapStringCell:     jitSnapAskStringCell,
		snapStringContent:  jitSnapAskStringContent,
		snapBigIntCell:     jitSnapAskBigIntCell,
		snapLiteral:        jitSnapAskLiteral,
		snapClosure:        jitSnapAskClosure,
		snapDefine:         jitSnapAskDefine,
		snapCharCode:       jitSnapAskCharCode,
		snapSubstring:      jitSnapAskSubstring,
		snapFromCharCode:   jitSnapAskFromCharCode,
		snapIntrinsic:      jitSnapAskIntrinsic,
		snapInstanceOf:     jitSnapAskInstanceOf,
		snapInline:         jitSnapAskInline,
		snapNativeCalls:    jitSnapAskNativeCalls,
		snapStringRead:     jitSnapAskStringRead,
		snapTypedRead:      jitSnapAskTypedRead,
		snapKeyedRead:      jitSnapAskKeyedRead,
		snapForEach:        jitSnapAskForEach,
		snapCalledClosure:  jitSnapAskCalledClosure,
		snapCallShape:      jitSnapAskCallShape,
		snapIndexOf:        jitSnapAskIndexOf,
		snapLeaf:           jitSnapAskLeaf,
		snapBigString:      jitSnapAskBigString,
		snapParseInt:       jitSnapAskParseInt,
		snapBigInt:         jitSnapAskBigInt,
		snapBigIntWide:     jitSnapAskBigIntWide,
		snapBigIntFailed:   jitSnapAskBigIntFailed,
		snapGeneric:        jitSnapAskGeneric,
		snapEntryGeneric:   jitSnapAskEntryGeneric,
		snapResumed:        jitSnapAskResumed,
		snapGlobal:         jitSnapAskGlobal,
		snapStringProperty: jitSnapAskStringProperty,
		snapProperty:       jitSnapAskProperty,
	}
}
